const waitlistJoin = `-- name: WaitlistJoin :one
INSERT INTO waitlists (id, event_id, tier_id, user_id, qty) VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (event_id, tier_id, user_id) DO UPDATE SET qty = EXCLUDED.qty,
  status = CASE WHEN waitlists.status IN ('expired','cancelled') THEN 'waiting' ELSE waitlists.status END,
  created_at = CASE WHEN waitlists.status IN ('expired','cancelled') THEN now() ELSE waitlists.created_at END
RETURNING id, event_id, tier_id, user_id, qty, status, offered_until, hold_id, created_at
`

type WaitlistJoinParams struct {
	ID      string `db:"id" json:"id"`
	EventID string `db:"event_id" json:"event_id"`
	TierID  string `db:"tier_id" json:"tier_id"`
	UserID  string `db:"user_id" json:"user_id"`
	Qty     int    `db:"qty" json:"qty"`
}

func (q *Queries) WaitlistJoin(ctx context.Context, arg WaitlistJoinParams) (Waitlist, error) {
	row := q.db.QueryRow(ctx, waitlistJoin,
		arg.ID,
		arg.EventID,
		arg.TierID,
		arg.UserID,
		arg.Qty,
	)
	var i Waitlist
	err := row.Scan(
		&i.ID,
		&i.EventID,
		&i.TierID,
		&i.UserID,
		&i.Qty,
		&i.Status,
		&i.OfferedUntil,
		&i.HoldID,
		&i.CreatedAt,
	)
	return i, err
}

